<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require BASE_PATH.'/app/AdminUi.php';$user=Auth::requireLogin();Auth::requirePermission('trips.manage');$pdo=Database::connection();$error='';$isCompany=($user['role']??'')==='company_manager';$ownCompany=(int)($user['company_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();try{$id=(int)($_POST['id']??0);$company=$isCompany?$ownCompany:(int)($_POST['company_id']??0);$from=(int)($_POST['origin_city_id']??0);$to=(int)($_POST['destination_city_id']??0);$departure=$_POST['departure_at']??'';$arrival=$_POST['arrival_at']?:null;$price=(float)($_POST['price']??-1);$seats=(int)($_POST['seats_total']??0);$status=in_array($_POST['status']??'available',['available','full','paused','cancelled','completed'],true)?$_POST['status']:'available';$published=isset($_POST['is_published'])?1:0;$tripClass=in_array($_POST['trip_class']??'regular',['regular','vip'],true)?$_POST['trip_class']:'regular';$vehicleDescription=trim($_POST['vehicle_description']??'');$image=upload_image_file('trip_image','trip');if(!$company||!$from||!$to||$from===$to||!$departure||$price<0||$seats<1)throw new RuntimeException('أكمل بيانات الرحلة بشكل صحيح.');if($id){$check=$pdo->prepare('SELECT company_id,image_path FROM trips WHERE id=?');$check->execute([$id]);$old=$check->fetch();if(!$old||($isCompany&&(int)$old['company_id']!==$ownCompany))throw new RuntimeException('لا تملك صلاحية تعديل هذه الرحلة.');$image=$image??$old['image_path'];$confirmed=$pdo->prepare("SELECT COALESCE(SUM(passengers_count),0) FROM bookings WHERE trip_id=? AND status='confirmed'");$confirmed->execute([$id]);if($seats<(int)$confirmed->fetchColumn())throw new RuntimeException('لا يمكن تقليل المقاعد عن عدد المقاعد المحجوزة والمؤكدة.');$pdo->prepare('UPDATE trips SET company_id=?,origin_city_id=?,destination_city_id=?,departure_at=?,arrival_at=?,vehicle_type=?,vehicle_description=?,image_path=?,trip_class=?,price=?,currency=?,seats_total=?,status=?,is_published=?,details=? WHERE id=?')->execute([$company,$from,$to,$departure,$arrival,trim($_POST['vehicle_type']??''),$vehicleDescription,$image,$tripClass,$price,$_POST['currency']??'SAR',$seats,$status,$published,trim($_POST['details']??''),$id]);admin_log($pdo,$user,'trip.updated','trip',$id,'تعديل رحلة');}else{$pdo->prepare('INSERT INTO trips(company_id,origin_city_id,destination_city_id,departure_at,arrival_at,vehicle_type,vehicle_description,image_path,trip_class,price,currency,seats_total,status,is_published,details,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$company,$from,$to,$departure,$arrival,trim($_POST['vehicle_type']??''),$vehicleDescription,$image,$tripClass,$price,$_POST['currency']??'SAR',$seats,$status,$published,trim($_POST['details']??''),$user['id']]);$id=(int)$pdo->lastInsertId();admin_log($pdo,$user,'trip.created','trip',$id,'إضافة رحلة');}redirect('/admin/trips.php?saved=1');}catch(Throwable $e){$error=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM trips WHERE id=?'.($isCompany?' AND company_id=?':''));$q->execute($isCompany?[(int)$_GET['edit'],$ownCompany]:[(int)$_GET['edit']]);$edit=$q->fetch()?:null;}
$cities=$pdo->query('SELECT id,name_ar FROM cities WHERE is_active=1 ORDER BY name_ar')->fetchAll();if($isCompany){$q=$pdo->prepare("SELECT id,name FROM companies WHERE id=? AND status='active'");$q->execute([$ownCompany]);$companies=$q->fetchAll();$sql='SELECT t.*,c.name company_name,o.name_ar origin_name,d.name_ar destination_name FROM trips t JOIN companies c ON c.id=t.company_id JOIN cities o ON o.id=t.origin_city_id JOIN cities d ON d.id=t.destination_city_id WHERE t.company_id=? ORDER BY t.departure_at DESC LIMIT 300';$q=$pdo->prepare($sql);$q->execute([$ownCompany]);$rows=$q->fetchAll();}else{$companies=$pdo->query("SELECT id,name FROM companies WHERE status='active' ORDER BY name")->fetchAll();$rows=$pdo->query('SELECT t.*,c.name company_name,o.name_ar origin_name,d.name_ar destination_name FROM trips t JOIN companies c ON c.id=t.company_id JOIN cities o ON o.id=t.origin_city_id JOIN cities d ON d.id=t.destination_city_id ORDER BY t.departure_at DESC LIMIT 300')->fetchAll();}
admin_page_start('إدارة الرحلات',$user);if($error)echo '<p class="notice danger">'.e($error).'</p>';if(isset($_GET['saved']))echo '<p class="notice">تم حفظ الرحلة.</p>';$v=fn($k,$d='')=>e($edit[$k]??$d);echo '<section class="panel"><h2>'.($edit?'تعديل الرحلة':'إضافة رحلة').'</h2><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="_csrf" value="'.e(Security::csrf()).'"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'">';
if(!$isCompany){echo '<label>الشركة<select name="company_id" required>';foreach($companies as $c)echo '<option value="'.(int)$c['id'].'" '.((int)($edit['company_id']??0)===(int)$c['id']?'selected':'').'>'.e($c['name']).'</option>';echo '</select></label>';}
foreach([['origin_city_id','مدينة الانطلاق'],['destination_city_id','مدينة الوصول']] as [$key,$label]){echo '<label>'.e($label).'<select name="'.$key.'" required>';foreach($cities as $c)echo '<option value="'.(int)$c['id'].'" '.((int)($edit[$key]??0)===(int)$c['id']?'selected':'').'>'.e($c['name_ar']).'</option>';echo '</select></label>';}
echo '<label>موعد الانطلاق<input type="datetime-local" name="departure_at" required value="'.($edit?e(date('Y-m-d\TH:i',strtotime($edit['departure_at']))):'').'"></label><label>موعد الوصول<input type="datetime-local" name="arrival_at" value="'.($edit&&!empty($edit['arrival_at'])?e(date('Y-m-d\TH:i',strtotime($edit['arrival_at']))):'').'"></label><label>نوع المركبة<input name="vehicle_type" value="'.$v('vehicle_type').'"></label><label>تصنيف الرحلة<select name="trip_class"><option value="regular" '.(($edit['trip_class']??'regular')==='regular'?'selected':'').'>عادية</option><option value="vip" '.(($edit['trip_class']??'regular')==='vip'?'selected':'').'>VIP</option></select></label><label>صورة الحافلة / الرحلة<input type="file" name="trip_image" accept="image/png,image/jpeg,image/webp"></label><label class="wide">وصف الحافلة<textarea name="vehicle_description">'.$v('vehicle_description').'</textarea></label><label>السعر<input type="number" min="0" step=".01" name="price" required value="'.$v('price','0').'"></label><label>العملة<select name="currency"><option value="SAR">ريال سعودي</option><option value="YER">ريال يمني</option></select></label><label>عدد المقاعد<input type="number" min="1" name="seats_total" required value="'.$v('seats_total','1').'"></label><label>الحالة<select name="status">';foreach(['available'=>'متاحة','full'=>'مكتملة','paused'=>'متوقفة','cancelled'=>'ملغاة','completed'=>'منتهية'] as $k=>$label)echo '<option value="'.$k.'" '.(($edit['status']??'available')===$k?'selected':'').'>'.$label.'</option>';echo '</select></label><label>نشر للعامة<input type="checkbox" name="is_published" '.((int)($edit['is_published']??1)===1?'checked':'').'></label>'.(!empty($edit['image_path'])?'<div class="wide">الصورة الحالية<br><img src="'.e($edit['image_path']).'" alt="صورة الرحلة" style="max-width:300px;max-height:150px;object-fit:cover"></div>':'').'<label class="wide">التفاصيل<textarea name="details">'.$v('details').'</textarea></label><button class="btn btn-primary">حفظ الرحلة</button>'.($edit?'<a class="admin-link" href="/admin/trips.php">إلغاء</a>':'').'</form></section><section class="panel"><table><thead><tr><th>الشركة</th><th>المسار</th><th>الموعد</th><th>السعر</th><th>المقاعد</th><th>التصنيف</th><th>النشر</th><th>الحالة</th><th></th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['company_name']).'</td><td>'.e($r['origin_name'].' - '.$r['destination_name']).'</td><td>'.e($r['departure_at']).'</td><td>'.e($r['price'].' '.$r['currency']).'</td><td>'.(int)$r['seats_total'].'</td><td>'.(($r['trip_class']??'regular')==='vip'?'VIP':'عادية').'</td><td>'.((int)$r['is_published']===1?'منشورة':'مسودة').'</td><td>'.e($r['status']).'</td><td><a class="admin-link" href="/admin/trips.php?edit='.(int)$r['id'].'">تعديل</a></td></tr>';if(!$rows)echo '<tr><td colspan="9">لا توجد رحلات.</td></tr>';echo '</tbody></table></section>';admin_page_end();
